import { ASK_TEMPLATES, type MapAtom, type Part, parse } from './reference-ask';

/**
 * The fake agent's grammar, generated by code from the approved map and the section 5 table (docs/estate.md, "The
 * ask templates"), never from what the generator says about itself (`askBuild`): the ask and hypothetical rows of
 * the table, every act text an atom's declared words give in every act row with one `{span}` (and each fixed tool
 * act, for the guards whose matcher lists its tool and the rules they enforce), and every situation text of the
 * map. The fake sets an atom off only when an ask equals a template with each act slot one of the atom's act texts
 * and each situation slot one situation text, byte for byte (dispatch.mjs, matchAsk). A `hypothetical` row asks what
 * an act would mean and sets nothing off. Nothing reads a word of an ask.
 */
export type AskGrammar = {
  templates: Array<{ kind: string; template: string }>;
  acts: Record<string, string[]>;
  situations: string[];
};

type Fill = { act?: string; situation?: string; span?: string };

/** A template with its slots filled, the optional group written when `withGroup`; undefined if a slot is empty. */
function render(parts: readonly Part[], fill: Fill, withGroup: boolean): string | undefined {
  let out = '';
  for (const part of parts) {
    if ('lit' in part) out += part.lit;
    else if ('opt' in part) {
      if (!withGroup) continue;
      const inner = render(part.opt, fill, true);
      if (inner === undefined) return undefined;
      out += inner;
    } else {
      const value = fill[part.slot as keyof Fill];
      if (value === undefined) return undefined;
      out += value;
    }
  }
  return out;
}

const hasGroup = (parts: readonly Part[]): boolean => parts.some((part) => 'opt' in part);

const hasWord = (text: string): boolean => /[\p{L}\p{N}]/u.test(text) && text.trim() === text;

/**
 * The text a situation gives: the whole field, verbatim (docs/estate.md section 5: a span of a gate's trigger, of
 * an atom's situation or of its passage is the whole field, never a part of it).
 */
function wholeText(text: string): string[] {
  return hasWord(text) ? [text] : [];
}

/**
 * The acts an atom gives, by what the map declares (lead ruling on gen.task): where the atom declares an act, its
 * declared text only (`fields.ask`, a route's request cell or a rule's request with its context; `fields.trigger`,
 * a gate's governed action; each labelled governed-action span of its quote), so an ask that drops it for other
 * words of the atom sets the atom off nowhere. Where it declares none, the source text it is read from, whole: its
 * situation (a unit's description, a rule's situation) and its quote. Empty when it has neither.
 */
export function declaredActs(atom: MapAtom): Array<{ text: string; context?: string }> {
  const fields = (atom.fields ?? {}) as { ask?: unknown; labelSpans?: unknown; trigger?: unknown };
  const acts: Array<{ text: string; context?: string }> = [];
  const push = (text: unknown, context?: unknown) => {
    if (typeof text !== 'string' || !hasWord(text) || acts.some((act) => act.text === text)) return;
    acts.push(typeof context === 'string' && hasWord(context) ? { text, context } : { text });
  };
  const ask = fields.ask;
  if (typeof ask === 'string') push(ask);
  else if (ask !== null && typeof ask === 'object') {
    const { text, context } = ask as { text?: unknown; context?: unknown };
    push(text, context);
  }
  push(fields.trigger);
  const quote = atom.provenance?.quote;
  const spans = (Array.isArray(fields.labelSpans) ? fields.labelSpans : []) as Array<{
    kind?: unknown;
    from?: unknown;
    to?: unknown;
  }>;
  if (typeof quote === 'string')
    for (const span of spans)
      if (span.kind === 'governed-action') push(quote.slice(Number(span.from), Number(span.to)));
  if (acts.length > 0) return acts;
  // No declared act: the ruled frame asks from the source text, whole.
  if (typeof atom.situation === 'string') for (const text of wholeText(atom.situation)) push(text);
  push(quote);
  return acts;
}

export function askGrammar(atoms: readonly MapAtom[]): AskGrammar {
  const asked = new Set(['ask', 'hypothetical']);
  const templates = ASK_TEMPLATES.filter((entry) => asked.has(entry.kind)).map((entry) => ({
    kind: entry.kind,
    template: entry.template,
  }));
  const byId = new Map(atoms.map((atom) => [atom.id, atom]));
  const acts = new Map<string, Set<string>>();
  const add = (text: string | undefined, id: string) => {
    if (text !== undefined) acts.set(text, (acts.get(text) ?? new Set()).add(id));
  };
  // The act rows with one `{span}`: each declared act is written in each of them, and is a {span} itself.
  const actRows = ASK_TEMPLATES.filter((entry) => entry.kind === 'act')
    .map((entry) => parse(entry.template))
    .filter((parts) => parts.filter((part) => 'slot' in part).length === 1 && !hasGroup(parts));
  const situations = new Set<string>();
  for (const atom of atoms) {
    for (const declared of declaredActs(atom)) {
      add(declared.text, atom.id);
      for (const row of actRows) add(render(row, { span: declared.text }, false), atom.id);
    }
    const ask = (atom.fields as { ask?: unknown } | undefined)?.ask;
    const context =
      ask !== null && typeof ask === 'object' ? (ask as { context?: unknown }).context : undefined;
    for (const text of [context, atom.situation])
      if (typeof text === 'string') for (const cut of wholeText(text)) situations.add(cut);
  }
  // A fixed tool act sets off the guards whose matcher lists its tool, and the rules they enforce; the one fixed
  // act the table ties to no tool (a hazard's) sets off the hazards.
  for (const row of ASK_TEMPLATES) {
    const slotted = parse(row.template).some((part) => 'slot' in part);
    if (row.kind !== 'act' || slotted) continue;
    if (row.tools === undefined) {
      for (const atom of atoms) if (atom.kind === 'hazard') add(row.template, atom.id);
      continue;
    }
    for (const atom of atoms) {
      const matcher = (atom.fields as { matcher?: unknown } | undefined)?.matcher;
      if (atom.kind !== 'guard' || typeof matcher !== 'string') continue;
      if (!matcher.split('|').some((tool) => row.tools?.includes(tool))) continue;
      for (const id of [atom.id, ...namedIn(atom.fields, byId)]) add(row.template, id);
    }
  }
  const sorted = <T>(values: Iterable<T>) => [...values].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return {
    templates,
    acts: Object.fromEntries(sorted(acts.keys()).map((text) => [text, sorted(acts.get(text) ?? [])])),
    situations: sorted(situations),
  };
}

/** The atom ids the fields of an atom name, at any depth up to three (a guard names the rule it enforces). */
function namedIn(value: unknown, byId: ReadonlyMap<string, MapAtom>, depth = 0): string[] {
  if (typeof value === 'string') return byId.has(value) ? [value] : [];
  if (Array.isArray(value) && depth < 3) return value.flatMap((item) => namedIn(item, byId, depth + 1));
  if (value !== null && typeof value === 'object' && depth < 3)
    return Object.values(value).flatMap((item) => namedIn(item, byId, depth + 1));
  return [];
}
